'use strict';
const CFG=window.APP_CONFIG, mode=document.body.dataset.mode, $=s=>document.querySelector(s), app=$('#app'), dialog=$('#dialog');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const META={
 '001':{title:'Reschedule delivery',person:'Vessa Lorne',object:'DL-001',kind:'booking',date:'3 February 2026',item:'Desk lamp',summary:'The customer cannot receive the morning delivery. Dispatch has offered two free windows; the customer needs to choose one.',draft:'Offer 3 February, 15:00–18:00 or 4 February, 10:00–13:00 UTC. Both are free. Ask the customer to choose before changing the booking.',recipient:'Vessa Lorne · customer',current:'3 February, 09:00–12:00 UTC'},
 '008':{title:'Get delivery windows and price',person:'Nemi',object:'DL-008',kind:'quote',date:'10 February 2026',item:'Your parcel',summary:'The customer wants a two-hour window instead of an all-day delivery. Dispatch must confirm availability and the full surcharge.',draft:'Request two-hour windows on 10 February for DL-008 and the full price. Do not change the booking before customer consent.',recipient:'Scheduling · Plover Arc Logistics',current:'10 February · all day'},
 '024':{title:'Locate the parcel',person:'Customer DL-024',object:'DL-024',kind:'investigation',date:'25 February 2026',item:'Your parcel',summary:'Delivery is recorded at 08:10, but the customer reports not receiving the parcel. An investigation is needed; loss has not been established.',draft:'Request an investigation for DL-024: compare the delivery record with the customer report and check the handover and route. Confirm registration of the investigation.',recipient:'Carrier investigations team',current:'Delivery disputed'},
 '031':{title:'Get a return label',person:'Customer DL-031',object:'RT-031',kind:'label',date:'4 March 2026',item:'Item return',summary:'Return RT-031 is already approved. Order TG-031 has no label. Obtain the document for this return; do not ask for another refusal confirmation.',draft:'Request a printable label for RT-031 linked to TG-031 and DL-031. Obtain the document through the verified returns channel.',recipient:'Labels team · Tallowmere Goods',current:'Return approved · no label yet'},
 '033':{title:'Rebook collection',person:'Customer RT-033',object:'RT-033',kind:'collection',date:'7 March 2026',item:'Return parcel',summary:'The previous collection was missed. The return is approved and the customer has chosen 7 March, 10:00–14:00 UTC. There is no surcharge; the customer still has the parcel.',draft:'Request collection RT-033 on 7 March, 10:00–14:00 UTC. Booking confirmation and the later physical handover receipt are separate outcomes.',recipient:'Collections control · Plover Arc Logistics',current:'Agreed: 7 March, 10:00–14:00 UTC'},
 'SIM':{title:'Refusal and separate collection',person:'Demo customer',object:'SIM-REFUSAL',kind:'refusal',date:'Demo scenario',item:'Demo order',summary:'A separate scenario from the original idea: record a refusal, then arrange an independently authorised return. This is not an organiser case.',draft:'Wait for the customer to confirm refusal. Collection requires a separate basis and agreed terms.',recipient:'Demo returns team',current:'Awaiting customer decision'}
};
const SLOTS=[{id:'s1',date:'3 February 2026',time:'15:00–18:00',price:0,currency:'GBP'},{id:'s2',date:'4 February 2026',time:'10:00–13:00',price:0,currency:'GBP'}];
const STATUS={retry_ready:['Request not executed','pending'],draft:['Draft',''],await_customer:['Awaiting customer','pending'],sending:['Sending','pending'],quote_wait:['Awaiting windows and price','pending'],offered:['Customer choice needed','pending'],booking_wait:['Awaiting dispatch','pending'],label_wait:['Awaiting label','pending'],collection_wait:['Awaiting collection confirmation','pending'],investigation_wait:['Awaiting registration','pending'],booked:['Reschedule confirmed','success'],label_ready:['Label ready','success'],collection_booked:['Collection booked','success'],investigation_registered:['Investigation opened','success'],unknown:['Outcome unknown','unknown'],no_options:['No available windows','pending'],stopped:['Agent stopped',''],refusal_saved:['Refusal recorded','success']};
let selected=new URLSearchParams(location.search).get('case')||'001';if(!META[selected])selected='001';let section='cases',tab='overview',filter='all',query='',clientStep='choose',storageOK=true,lastFocus=null,toastTimer;
function baseFresh(){return {version:CFG.version,records:Object.fromEntries(Object.keys(META).map(k=>[k,{stage:k==='SIM'?'await_customer':'draft',slots:k==='001'?structuredClone(SLOTS):[],selection:null,consent:null,revision:1,stop:false,help:null,rounds:0,pending:null,log:[],customDraft:null,notice:'',run:'UX-'+k+'-'+(globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2))}]))};}
let state;
try{const saved=localStorage.getItem(CFG.storageKey);state=saved?JSON.parse(saved):fresh();if(state.version!==CFG.version||!state.records||Object.keys(META).some(k=>!state.records[k]))state=fresh();}catch{state=fresh();storageOK=false;}
for(const r of Object.values(state.records)){if(r.stage==='sending'){r.stage='unknown';r.notice='Sending was interrupted. Check the outcome of the original request first.';if(r.pending)r.pending.status='unknown';log(r,'Page reopened after interrupted send','No automatic retry');}}
const rec=()=>state.records[selected],meta=()=>META[selected];
function save(){try{localStorage.setItem(CFG.storageKey,JSON.stringify(state));}catch{storageOK=false;}}
function log(r,title,detail=''){r.log.unshift({title,detail,time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})});}
function say(s){$('#toast').textContent=s;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',5000);}
function badge(r){const [t,c]=STATUS[r.stage]||['Pending','pending'];return `<span class="badge ${c}">${esc(t)}</span>${r.stop&&r.stage!=='stopped'?'<span class="badge">New actions stopped</span>':''}`;}
function button(text,action,kind='',disabled=false){return `<button type="button" class="${kind}" data-action="${action}" ${disabled?'disabled':''}>${text}</button>`;}
const money=s=>s.price===0?'No extra charge':`${s.price.toFixed(2)} ${s.currency}`;
const slotText=s=>s?`${s.date}, ${s.time} UTC`:'Not selected';
function toolbar(){return `<div class="prototype ${mode==='client'?'client-bar':''}"><span>UX-prototype · local simulation</span><nav><a href="team.html?case=${selected}" ${mode==='team'?'aria-current="page"':''}>Team</a><a href="client.html?case=${selected}" ${mode==='client'?'aria-current="page"':''}>Customer</a><a href="index.html">Overview</a><a href="intake.html">Local intake</a></nav></div>${!storageOK?'<div class="storage-warning">Storage unavailable: changes will last only until this page is closed.</div>':''}`;}
function brand(name){return `<div class="brand"><img class="brand-lockup" src="assets/brand/forward-paper.svg" alt="${esc(name)}" width="374"></div>`;}
function team(){const count=Object.values(state.records).filter(r=>r.help).length;return `<div class="app-shell"><aside class="sidebar">${brand(CFG.teamName)}<nav class="side-nav" aria-label="Workspaces">${[['cases','Cases','▤'],['queue','Operator queue','◎'],['prep','Simulation','⌘']].map(([k,t,i])=>`<button data-section="${k}" class="${section===k?'active':''}" ${section===k?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${i}</span>${t}${k==='queue'&&count?` <span class="badge">${count}</span>`:''}</button>`).join('')}</nav><div class="sidebar-footer"><div class="person"><span class="avatar">OP</span><div><strong class="small">Team operator</strong><div class="small muted">Demo role</div></div></div></div></aside><div class="workspace"><header class="topbar"><div class="crumb">Delivery & Logistics <span aria-hidden="true">/</span> <strong>${section==='cases'?'Cases':section==='queue'?'Queue':'Simulation'}</strong></div><div class="top-actions"><span class="badge">Simulation</span>${button('Demo events','demo','quiet')}</div></header><main id="main">${section==='cases'?casesView():section==='queue'?queueView():prepView()}</main></div></div>`;}
function casesView(){const done=Object.values(state.records).filter(r=>['booked','label_ready','collection_booked','investigation_registered'].includes(r.stage)).length;return `<div class="page-heading"><div><div class="eyebrow">Team workspace</div><h1>Every request has a next step</h1><p class="muted">Customer context, ownership and confirmed outcomes in one place.</p></div><span class="small muted">5 organiser cases + 1 demo</span></div><div class="stats"><div class="stat"><strong>${6-done}</strong><span>Tasks in progress</span></div><div class="stat"><strong>${Object.values(state.records).filter(r=>r.stage.includes('wait')||r.stage==='unknown').length}</strong><span>Awaiting a response</span></div><div class="stat"><strong>${done}</strong><span>Tasks completed</span></div></div><div class="case-layout"><section class="case-list" aria-label="Case list"><div class="list-toolbar"><input id="case-search" type="search" placeholder="ID, customer or task" aria-label="Search cases" value="${esc(query)}"><select id="case-filter" aria-label="Filter cases"><option value="all" ${filter==='all'?'selected':''}>All cases</option><option value="attention" ${filter==='attention'?'selected':''}>Action needed</option><option value="waiting" ${filter==='waiting'?'selected':''}>Awaiting a response</option><option value="done" ${filter==='done'?'selected':''}>Completed tasks</option><option value="mine" ${filter==='mine'?'selected':''}>My operator work</option></select></div><div id="case-rows">${rows()}</div></section><section class="case-detail" aria-label="Case details">${detail()}</section></div>`;}
function detail(){const m=meta(),r=rec();return `<div class="detail-head"><div><div class="eyebrow">${selected==='SIM'?'Demo scenario':'Delivery '+selected} · ${m.object}</div><h1>${m.title}</h1><p class="muted">${m.person} · ${r.stage==='booked'?esc(slotText(r.consent?.slot)):'Originally: '+m.current}</p></div><div>${badge(r)}</div></div><nav class="tabs" aria-label="Case sections">${[['overview','Summary'],['requests','Requests'],['sources','Sources']].map(([k,t])=>`<button data-tab="${k}" class="${tab===k?'active':''}" aria-pressed="${tab===k}">${t}</button>`).join('')}</nav><div class="detail-body"><div>${tab==='overview'?overview():tab==='sources'?sources():requests()}</div><aside class="detail-side"><section class="card"><h3>Task control</h3><dl class="kv"><div><dt>Owner</dt><dd>${r.help?'Team operator':'Delivery coordinator'}</dd></div><div><dt>Next step</dt><dd>${nextStep(r)}</dd></div><div><dt>Task outcome</dt><dd>${m.kind==='label'?'Obtain the label':m.kind==='investigation'?'Register investigation':m.kind==='collection'?'Rebook collection':'Confirm the specific task'}</dd></div><div><dt>Physical delivery / return</dt><dd>Not confirmed</dd></div></dl></section><section class="card"><h3>Activity</h3>${timeline(r)}<div class="actions">${button('Check status','check','quiet')}</div></section></aside></div>`;}
function timeline(r){return `<ol class="timeline">${r.log.slice(0,8).map(x=>`<li><strong>${esc(x.title)}</strong><span>${x.time} · ${esc(x.detail)}</span></li>`).join('')}<li><strong>Initial context loaded</strong><span>${selected==='SIM'?'Synthetic scenario':'Events 001–002 · before agent action'}</span></li></ol>`;}
function baseOverview(){const m=meta(),r=rec();return `<section class="card"><div class="card-title"><h2>What needs to happen</h2><span class="badge">Initial context</span></div><p class="summary">${m.summary}</p><dl class="facts"><div><dt>Object</dt><dd>${m.object}</dd></div><div><dt>Customer</dt><dd>${m.person}</dd></div></dl></section>${actionCard()}${r.help?`<div class="notice pending"><strong>${r.help.status==='requested'?'Operator handoff awaiting acknowledgement':r.help.status==='queued'?'Request in the operator queue':r.help.status==='accepted'?'Operator reviewing request':'Operator decision saved'}</strong><br>${esc(r.help.note||'The next step will appear after the decision.')}</div>`:''}<div class="actions">${button('Ask an operator','help','quiet',!!r.help&&r.help.status!=='resolved')}${button('Stop agent','stop','quiet',r.stop)}</div>`;}
function actionCard(){const r=rec(),m=meta();if(r.stage==='retry_ready')return `<section class="card"><h2>Non-execution confirmed</h2><p>The original request can be retried with the same parameters. Its type and ID will be retained.</p>${button('Retry original request','retry','primary',r.stop)}</section>`;if(r.stage==='unknown')return `<section class="card"><div class="notice unknown"><strong>Outcome still unknown</strong><p>The request may have been accepted. Reconcile its outcome before sending another action.</p></div>${button('Check outcome','check','primary')}<p class="small muted" style="margin-top:14px">The original request and its parameters are retained.</p></section>`;
 if(['booked','label_ready','collection_booked','investigation_registered','refusal_saved'].includes(r.stage))return `<section class="card"><div class="card-title"><h2>Confirmed outcome</h2><span class="badge success">Software check</span></div><p class="summary">${resultText(r)}</p><div class="notice success">Source: a new response from the local simulator in this run.</div>${r.stage==='label_ready'?button('View label','label'):''}${r.stage==='refusal_saved'?'<p>The separate return authorisation is confirmed in this demo. The customer still needs to agree collection terms.</p>':''}<p class="small muted">Task completion and physical receipt of the item are tracked separately.</p></section>`;
 if(r.stop)return `<section class="card"><h2>New actions stopped</h2><p>Confirmed outcomes are retained. Stopping does not cancel delivery or undo previous actions.</p>${button('Check status','check')}</section>`;
 if(r.stage!=='draft')return `<section class="card"><h2>${STATUS[r.stage][0]}</h2><p>${r.stage==='no_options'?'Dispatch confirmed that no suitable windows are available. Request another date or get help.':r.stage==='offered'?'Options and full prices received. Awaiting customer choice and consent.':'Request saved. Dispatch acknowledgement does not mean the task is complete.'}</p><div class="notice pending">${nextStep(r)}</div>${button('Check status','check')}${r.stage==='no_options'?button('Other dates','dates','quiet'):''}</section>`;
 return `<section class="card action-card"><div class="card-title"><h2>Proposed next step</h2><span class="badge ai">◇ AI agent draft</span></div><p class="small muted">Not sent · an authorised channel is required</p><div class="action-message">${esc(r.customDraft||m.draft)}</div><div class="small muted">To: <strong>${m.recipient}</strong></div><div class="actions">${button(m.kind==='quote'?'Request windows and price':m.kind==='label'?'Request label':m.kind==='collection'?'Request collection rebooking':m.kind==='investigation'?'Request investigation':'Invite customer to choose','send','primary',m.kind==='refusal')}${button('Edit','edit','quiet')}</div></section>`;
}
function baseResultText(r){if(r.stage==='booked')return `Booking ${meta().object}: ${esc(slotText(r.consent?.slot))}. ${money(r.consent?.slot||{price:0})}. Physical delivery is not yet confirmed.`;if(r.stage==='label_ready')return 'Label RT-031 received and linked to TG-031 / DL-031. The seller has not yet received the item.';if(r.stage==='collection_booked')return `Collection booked: ${esc(r.collectionDate||'7 March 2026')}, ${esc(r.collectionTime||'10:00–14:00')} UTC. Physical receipt of the parcel is not yet confirmed.`;if(r.stage==='investigation_registered')return 'Investigation registered. The location of the parcel remains unresolved; loss has not been established.';return 'Item refusal recorded. No collection request has been created yet.';}
function sources(){const d=window.SOURCE_DATA?.[selected];return `<section class="card"><div class="card-title"><h2>Original messages</h2><span class="badge">Before agent action</span></div><p class="small muted">Original text. A message is not independent verification of a fact or authority.</p>${d?d.events.map(e=>`<article class="source"><div class="source-meta"><span>${esc(e.event_id)}</span><span>${esc(e.occurred_at.replace('T',' ').replace('+00:00',' UTC'))}</span><span>${esc(e.channel)}</span></div><h3>${esc(e.sender)}</h3><div class="body">${esc(e.body)}</div><code>${esc(e.source_ref)}</code></article>`).join(''):'<p>Separate synthetic refusal scenario. Original organiser cases are unchanged.</p>'}<details><summary class="small muted">Input revision</summary><code class="small" style="overflow-wrap:anywhere">${esc(d?.input_hash||'synthetic-refusal-v1')}</code></details></section>`;}
function client(){const m=meta(),r=rec();return `<div class="client-shell"><header class="client-header">${brand(CFG.clientName)}<span class="badge">Order ${m.object}</span></header><main id="main" style="padding:0"><div class="client-title"><div class="eyebrow">Your request</div><h1>${clientTitle(r)}</h1><p class="muted">${clientSubtitle(r)}</p></div><section class="card client-card"><div class="order-strip"><span class="parcel-icon" aria-hidden="true">▱</span><div><strong>${m.item}</strong><span>${m.object} · ${r.stage==='booked'?esc(slotText(r.consent?.slot)):'Originally: '+m.current}</span></div></div>${clientContent()}</section>${r.help?`<div class="notice pending">${r.help.status==='requested'?'Requesting help. Queue acceptance is not yet confirmed.':r.help.status==='queued'?'Your request is in the queue. An operator will follow up.':r.help.status==='accepted'?'An operator is reviewing your question.':esc(r.help.note||'Operator decision saved.')}</div>`:''}<div class="client-tools">${button('Get help','help','quiet',!!r.help&&r.help.status!=='resolved')}${button('Check status','check','quiet')}${!r.stop?button('Stop new actions','stop','quiet'):''}</div><p class="client-footer">Request acknowledgement and delivery completion are separate events. We show what is confirmed and what is still pending.</p><details class="view-note"><summary>UX demo controls</summary><div class="field"><label for="client-case">Scenario</label><select id="client-case">${Object.keys(META).map(k=>`<option value="${k}" ${k===selected?'selected':''}>${k} · ${META[k].title}</option>`).join('')}</select></div>${button('Simulation events','demo','quiet')}<p class="small muted">These are prototype controls, not part of the customer product.</p></details></main></div>`;}
function clientTitle(r){if(r.stage==='booked')return 'New time confirmed';if(r.stage==='label_ready')return 'Label ready';if(r.stage==='collection_booked')return 'Collection booked';if(r.stage==='investigation_registered')return 'Investigation opened';if(r.stage==='unknown')return 'Checking the outcome';if(r.stop)return 'New actions stopped';if(r.stage==='no_options')return 'No windows on this date';if(r.stage==='refusal_saved')return 'Refusal recorded';if(r.stage.includes('wait')&&r.stage!=='await_customer'||r.stage==='sending')return meta().kind==='label'?'Preparing your label':'Your request is in progress';if(meta().kind==='refusal')return 'Record a refusal';if(meta().kind==='label')return 'Get a return label';if(meta().kind==='investigation')return 'Help locating your parcel';if(meta().kind==='collection')return 'Rebook parcel collection';return clientStep==='review'?'Review your chosen time':r.slots.length?'When can you receive your delivery?':'Check times and prices';}
function clientSubtitle(r){if(r.stage==='unknown')return 'The response is delayed. Do not send the request again.';if(r.stage==='booked')return 'The booking has changed. Physical delivery is still ahead.';if(r.stage==='label_ready')return 'The return is approved. Next, prepare your parcel.';if(r.stop)return 'Previous actions and their outcomes are retained.';return meta().kind==='booking'||meta().kind==='quote'?'Review the exact terms before you confirm.':'Your next step and confirmed outcome will appear here.';}
function baseClientContent(){const m=meta(),r=rec();if(r.stage==='retry_ready')return `<h2>Request not executed</h2><p>Non-execution has been verified. You can retry the same request without changing its terms.</p>${button('Retry request','retry','primary',r.stop)}`;if(['booked','label_ready','collection_booked','investigation_registered'].includes(r.stage))return `<div class="result-icon" aria-hidden="true">✓</div><h2>${STATUS[r.stage][0]}</h2><p>${resultText(r)}</p>${r.stage==='label_ready'?button('View label','label','primary'):''}<div class="notice success">Confirmation is saved in this demo request.</div>`;
 if(r.stage==='unknown')return `<div class="result-icon pending" aria-hidden="true">…</div><h2>We do not know whether the action completed</h2><p>We are checking the request already sent. This confirms neither success nor failure.</p>${r.stop?'<div class="notice">New actions are stopped. The previous request is still being checked.</div>':''}${button('Check result','check','primary')}`;
 if(r.stop)return '<h2>No new requests will be sent</h2><p>Stopping does not undo a completed reschedule, return or sent message.</p>';
 if(r.stage==='no_options')return '<h2>No suitable windows yet</h2><p>Dispatch checked availability. Choose another date or ask for help.</p>'+button('Choose another date','dates','primary');
 if(r.stage==='refusal_saved')return `<div class="notice success">Refusal confirmed. Collection has not been arranged yet.</div><h2>Arrange a separate collection</h2><p>The return is authorised in this demo scenario. Enter a suitable date and address.</p>${button('Enter collection details','collection-form','primary')}`;
 if(r.stage==='sending'||r.stage.includes('_wait'))return `<div class="result-icon pending" aria-hidden="true">…</div><h2>${STATUS[r.stage][0]}</h2><p>${r.stage==='quote_wait'?'We are requesting available two-hour windows and full prices. Your current delivery time has not changed.':r.stage==='label_wait'?'Your return is already approved. We are waiting for the label for RT-031; no new refusal confirmation is needed.':r.stage==='booking_wait'?`Selected: ${esc(slotText(r.consent?.slot))}. Awaiting dispatch confirmation.`:'Request saved. We will show the outcome once confirmed.'}</p><div class="notice pending">${r.stage==='sending'?'Sending. Resending is unavailable.':'You can return to this request later in the same browser.'}</div>${button('Refresh status','check','primary')}`;
 if(m.kind==='label')return '<h2>Return already approved</h2><p>RT-031 has no label yet. We will request it from the returns team; no new refusal is needed.</p>'+button('Request label','send','primary');
 if(m.kind==='collection')return `<h2>Terms already agreed</h2><p>7 March 2026, 10:00–14:00 UTC. Collection rebooking is free. You still have the parcel.</p><div class="notice">Your earlier consent remains valid. You do not need to confirm the return again.</div><p class="muted">The team will send the collection rebooking request.</p>`;
 if(m.kind==='investigation')return '<h2>Check the delivery record</h2><p>You reported not receiving the parcel. We will ask the carrier to check the handover and route.</p>'+button('Request investigation','send','primary');
 if(m.kind==='refusal')return '<h2>Confirm your choice</h2><p>We will record your refusal of the item. Returns, collections and refunds do not happen automatically.</p>'+button('Record a refusal','refusal-dialog','primary');
 if(!r.slots.length)return '<h2>First, get the exact terms</h2><p>We will request two-hour windows and full surcharges. Your delivery time will not change without your consent.</p>'+button('Get options and prices','send','primary');
 if(clientStep==='review'&&r.selection){const s=r.slots.find(x=>x.id===r.selection);if(!s){clientStep='choose';return clientContent();}return `<div class="steps" aria-label="Step 2 of 2"><span class="done"></span><span class="done"></span></div><h2>Does this look right?</h2><div class="summary-row"><span>Delivery</span><strong>${s.date}</strong></div><div class="summary-row"><span>Time</span><strong>${s.time} UTC</strong></div><div class="summary-row"><span>Full surcharge</span><strong>${money(s)}</strong></div><p class="small muted" style="margin-top:20px">By confirming, you agree to this exact time and price. Dispatch must confirm the booking change.</p>${button('Confirm reschedule','confirm-booking','primary')}<div class="actions">${button('Change selection','back-choice','quiet')}</div>`;}
 return `${r.notice?`<div class="notice pending">${esc(r.notice)}</div>`:''}<div class="steps" aria-label="Step 1 of 2"><span class="done"></span><span></span></div><h2>Available times</h2><fieldset style="border:0;padding:0;margin:0"><legend class="sr">Choose a delivery window</legend>${r.slots.map(s=>`<label class="slot"><input type="radio" name="slot" value="${s.id}" ${r.selection===s.id?'checked':''}><span class="slot-main"><strong>${s.date}</strong><span>${s.time} UTC</span></span><b>${money(s)}</b></label>`).join('')}</fieldset><p class="small muted">All times are UTC. Selecting a time does not change the booking yet.</p>${button('Continue','review','primary',!r.selection)}<div class="actions">${button('I need another date','dates','quiet')}</div>`;
}
function modal(title,body){lastFocus=document.activeElement;dialog.innerHTML=`${button('×','close','dialog-close')}<h2 id="dialog-title">${title}</h2>${body}`;dialog.querySelector('.dialog-close').setAttribute('aria-label','Close');dialog.showModal();(dialog.querySelector('input:not([type=hidden]),textarea,select')||dialog.querySelector('button:not(.dialog-close)')||dialog.querySelector('button')).focus();}
function close(){dialog.close();lastFocus?.focus();}
dialog.addEventListener('close',()=>lastFocus?.isConnected&&lastFocus.focus());
function baseAction(a){const r=rec(),m=meta();if(a==='close')return close();if(a==='demo')return demo();if(a==='check'){say(r.stage==='unknown'?'No new evidence. The request was not resent.':'Status refreshed. No new responses.');return;}if(a==='clear-filter'){query='';filter='all';render();return;}if(a==='go-cases'){section='cases';render();return;}
 if(a==='retry')return submit(r.pending?.kind,true);
 if(a==='send')return submit(m.kind==='booking'?'invite':m.kind);
 if(a==='review'){if(!r.selection)return;clientStep='review';render();$('#main h1')?.setAttribute('tabindex','-1');$('#main h1')?.focus();return;}
 if(a==='back-choice'){clientStep='choose';r.consent=null;render();return;}
 if(a==='confirm-booking'){const slot=r.slots.find(s=>s.id===r.selection);if(!slot||r.stop)return; r.consent={slot:structuredClone(slot),revision:r.revision,object:m.object};submit('booking');return;}
 if(a==='edit'){modal('Edit draft',`<form id="edit-form"><div class="field"><label for="draft-text">Message</label><textarea id="draft-text" required maxlength="1500">${esc(r.customDraft||m.draft)}</textarea></div><p class="small muted">Saving does not send a message or change permissions.</p><div class="dialog-actions"><button type="button" data-action="close">Cancel</button><button class="primary" type="submit">Save draft</button></div></form>`);return;}
 if(a==='dates'){if(r.stop)return say('New actions are stopped.');if(r.rounds>=r.dateAllowance)return say('The search limit has been reached. Ask an operator for help.');modal('Which date works for you?',`<form id="dates-form"><div class="field"><label for="date-input">Preferred date</label><input type="date" id="date-input" value="${selected==='001'?'2026-02-05':'2026-02-11'}" min="${selected==='001'?'2026-02-02':'2026-02-09'}" required></div><p class="muted">We will request availability and prices. Your current booking will not change.</p><div class="dialog-actions"><button type="button" data-action="close">Back</button><button class="primary" type="submit">Request options</button></div></form>`);return;}
 if(a==='stop'){modal('Stop new actions?',`<p>No new requests will be sent for this case. Completed actions are retained; any unknown outcome will still be checked.</p><p class="muted">This does not cancel a delivery or return.</p><div class="dialog-actions">${button('Keep working','close')}${button('Stop agent','confirm-stop','primary')}</div>`);return;}
 if(a==='confirm-stop'){close();r.stop=true;if(r.stage==='sending'||r.stage.endsWith('_wait'))r.stage='unknown';else if(!['booked','label_ready','collection_booked','investigation_registered','refusal_saved','unknown'].includes(r.stage))r.stage='stopped';log(r,'Stop saved','New actions blocked');render();say('Stop confirmed by the local simulator.');return;}
 if(a==='help'){if(r.help)return;r.help={status:'requested',note:''};const id=selected;log(r,'Help requested','Awaiting queue acceptance');render();say('Help request sent.');setTimeout(()=>{if(state.records[id].help?.status!=='requested')return;state.records[id].help.status='queued';log(state.records[id],'Queue accepted the request','Owner: team operator');render();say('Request accepted into the operator queue.');},450);return;}
 if(a==='label'){modal('Return label RT-031',`<div class="notice">Demo document · not valid for shipping</div><dl class="facts"><div><dt>Return</dt><dd>RT-031</dd></div><div><dt>Order</dt><dd>TG-031</dd></div><div><dt>Original delivery</dt><dd>DL-031</dd></div><div><dt>Destination</dt><dd>Return to seller</dd></div></dl><p>The live product would show a verified document from the returns team here. The later historical attachment is not loaded into this prototype.</p><div class="dialog-actions">${button('Close','close','primary')}</div>`);return;}
 if(a==='refusal-dialog'){modal('Record refusal of this item?',`<p>Confirm refusal for SIM-REFUSAL. This is a separate record; collection and refund are not created automatically.</p><div class="dialog-actions">${button('Back','close')}${button('Confirm refusal','confirm-refusal','primary')}</div>`);return;}
 if(a==='confirm-refusal'){close();return submit('refusal');}
 if(a==='collection-form'){modal('Collection details',`<form id="collection-form"><div class="field"><label for="pickup-date">Date</label><input type="date" id="pickup-date" required value="2026-03-07"></div><div class="field"><label for="pickup-address">Collection address</label><input id="pickup-address" required placeholder="Enter the address"></div><p>Demo window: 10:00–14:00 UTC · no extra charge.</p><label class="checkline"><input type="checkbox" required><span>I agree to a separate collection on these terms.</span></label><div class="dialog-actions">${button('Back','close')}<button type="submit" class="primary">Request collection</button></div></form>`);return;}
 if(a==='reset'){modal('Restart the demo?',`<p>Only local results in this UX prototype will be reset. Source JSON will not change.</p><div class="dialog-actions">${button('Cancel','close')}${button('Reset demo','confirm-reset','primary')}</div>`);return;}
 if(a==='confirm-reset'){close();state=fresh();clientStep='choose';render();say('Local demo reset.');return;}
 if(a.startsWith('event-')){close();if(a==='event-confirm')return confirmEvent();if(a==='event-unknown'){r.stage='unknown';log(r,'Outcome unknown','Simulator response lost');}if(a==='event-empty'){r.stage=r.stop?'stopped':'no_options';r.slots=[];r.selection=null;r.consent=null;log(r,'No windows available','Confirmed simulator response');}if(a==='event-none'){r.stage=r.stop?'stopped':'retry_ready';log(r,'Non-execution verified','Only the original intent can be retried');}if(a==='event-stale'){r.revision++;r.selection=null;r.consent=null;clientStep='choose';r.stage='offered';r.notice='The offer has changed. Review the terms and choose a time again.';log(r,'Terms updated','Previous consent no longer applies');}render();return;}
}
// Local state and evidence model. No command leaves this prototype.
function scenarioClock(id){return {'001':'2026-02-02T09:10:00Z','008':'2026-02-09T09:10:00Z','024':'2026-02-25T09:10:00Z','031':'2026-03-04T09:10:00Z','033':'2026-03-06T09:10:00Z','SIM':'2026-03-06T09:10:00Z'}[id];}
function fresh(){const s=baseFresh();for(const [id,r] of Object.entries(s.records)){Object.assign(r,{clock:scenarioClock(id),requests:[],responses:[],decisions:[],budget:{requests:0,maxRequests:6,checks:0,maxChecks:3},wait:null,dateAllowance:2,collectionConsent:null,returnAuthority:'approved',channelAllowed:true,stopState:'none',resultClosed:false,snapshot:CFG.snapshotHashes[id]||'synthetic-refusal-v1',configVersion:'local-v4',refusalReason:''});}s.prep={phase:'draft',revision:1,config:{caseId:'001',clock:scenarioClock('001'),workflow:'v6',simulator:'local-v4',maxRequests:6,maxChecks:3,channel:'allowed',rehearsal:'normal'},errors:[]};return s;}
function terminal(r){return ['booked','label_ready','collection_booked','investigation_registered','refusal_saved'].includes(r.stage);}
function outstanding(r){return !!r.pending&&['sending','unknown','await_customer'].concat(['quote_wait','booking_wait','label_wait','collection_wait','investigation_wait']).includes(r.stage);}
function dateISO(r){return r.clock.slice(0,10);}
function plusMinutes(clock,n){return new Date(Date.parse(clock)+n*60000).toISOString();}
function fmtClock(clock){return new Date(clock).toLocaleString('en-GB',{timeZone:'UTC',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})+' UTC';}
function rememberRequest(r){if(!r.pending)return;const i=r.requests.findIndex(x=>x.id===r.pending.id);const copy=structuredClone(r.pending);if(i<0)r.requests.push(copy);else r.requests[i]=copy;}
function render(target){const active=document.activeElement;let selector=target;if(!selector&&active&&app.contains(active)){if(active.id)selector='#'+CSS.escape(active.id);else for(const key of ['action','case','tab','section','operator'])if(active.dataset[key]){selector=`[data-${key}="${CSS.escape(active.dataset[key])}"]`;break;}}for(const r of Object.values(state.records))rememberRequest(r);app.innerHTML=toolbar()+(mode==='team'?team():client());save();if(selector){const el=app.querySelector(selector)||app.querySelector('#main h1');if(el){if(!el.matches('button,input,select,textarea,a'))el.tabIndex=-1;el.focus({preventScroll:true});}}}
function nextStep(r){if(r.stopState==='requested')return 'Confirm that the stop is registered';if(r.help?.status==='awaiting_customer')return 'Customer: answer the operator';if(r.manual)return 'Team operator: review the pending obligation';if(r.stop)return outstanding(r)?'Reconcile the previous request':'No new actions; retained outcomes remain visible';if(r.stage==='unknown')return 'Reconcile the original request; do not resend';if(r.stage==='retry_ready')return 'Retry the same intent after verified non-execution';if(r.stage==='await_customer'||r.stage==='offered')return 'Customer: review terms and choose';if(r.stage.endsWith('_wait'))return 'Wait for the named owner until the next check';if(r.stage==='draft')return 'Review and send the request';if(r.stage==='no_options')return 'Choose another date or ask an operator';return 'Review the confirmed task outcome';}
function waitCard(r){if(!r.wait||!outstanding(r))return '';if(mode==='client')return `<div class="notice pending"><strong>${r.manual?'The support team is reviewing your request':'Waiting for a delivery update'}</strong><p>Next update: ${fmtClock(r.wait.next)}. Response deadline: ${fmtClock(r.wait.due)}.</p><p>${r.manual?'Automatic checks have ended. Your unresolved request is with the support team.':'We are checking the existing request. No duplicate request will be sent.'}</p></div>`;return `<section class="card"><h3>Pending obligation</h3><dl class="kv"><div><dt>Response owner</dt><dd>${esc(r.wait.owner)}</dd></div><div><dt>Next check</dt><dd>${fmtClock(r.wait.next)}</dd></div><div><dt>Response deadline</dt><dd>${fmtClock(r.wait.due)}</dd></div><div><dt>Run budget</dt><dd>${r.budget.checks}/${r.budget.maxChecks} status checks · ${r.budget.requests}/${r.budget.maxRequests} commands</dd></div><div><dt>Fallback owner</dt><dd>Team operator</dd></div></dl>${r.manual?'<div class="notice pending">Automatic work is paused. The pending outcome is retained for operator review.</div>':''}</section>`;}
function escalation(r,reason){r.manual=true;r.notice=reason;if(!r.help||r.help.status==='resolved')r.help={status:'queued',note:reason,requestedAt:r.clock,due:plusMinutes(r.clock,60),savedStage:r.stage,revision:r.revision};log(r,'Bounded fallback',reason);}
function checkOutcome(){const r=rec();if(['requested','failed'].includes(r.stopState)){r.stopState='acknowledged';render();return say('Stop registration verified. New actions remain blocked.');}if(!outstanding(r))return say('Status checked. No unresolved external request.');if(r.budget.checks>=r.budget.maxChecks||Date.parse(r.clock)>=Date.parse(r.wait?.due||r.clock)){escalation(r,'Response deadline or shared checking budget reached. Operator review is required.');render();return say('Automatic checking ended. The operator owns the pending outcome.');}r.budget.checks++;r.clock=plusMinutes(r.clock,5);r.wait.next=plusMinutes(r.clock,5);log(r,'Outcome checked','No new response; no command resent');if(r.budget.checks>=r.budget.maxChecks)escalation(r,'Shared checking budget reached. Pending outcome retained.');render();say('No new evidence. The original request was not resent.');}
function requests(){const r=rec();return `<section class="card"><h2>Requests and confirmations</h2><p class="small muted">Run ${esc(r.run)} · workflow v6 · ${esc(r.configVersion)} · input ${esc(r.snapshot)}</p>${r.requests.length?r.requests.map(q=>`<details class="evidence-record" open><summary>${esc(q.kind)} · ${esc(q.status)} · ${esc(q.id)}</summary><dl class="facts"><div><dt>Object / revision</dt><dd>${esc(q.object)} / ${q.revision}</dd></div><div><dt>Recipient / channel</dt><dd>${esc(q.recipient)} / ${esc(q.channel)}</dd></div><div><dt>Created / attempts</dt><dd>${fmtClock(q.createdAt)} / ${q.attempts}</dd></div><div><dt>Expected evidence</dt><dd>${esc(q.expected)}</dd></div></dl><p class="source body">${esc(q.body)}</p><details><summary>Exact intent and consent</summary><pre>${esc(JSON.stringify(q.params,null,2))}</pre></details>${r.responses.filter(x=>x.requestId===q.id).map(x=>`<article class="response-record"><strong>${x.accepted?'Verified response':'Rejected evidence'}</strong><p>${esc(x.reason||x.outcome)} · ${esc(x.provider)} · ${fmtClock(x.receivedAt)}</p><dl class="facts"><div><dt>Object / revision</dt><dd>${esc(x.object)} / ${x.revision}</dd></div><div><dt>Evidence reference</dt><dd>${esc(x.id)}</dd></div></dl><pre>${esc(JSON.stringify(x.payload,null,2))}</pre></article>`).join('')}</details>`).join(''):'<p>No request has been sent yet.</p>'}</section>`;}
function submit(kind,retry=false){const r=rec(),m=meta();if(r.stop||r.stopState==='requested'||r.stage==='sending'||r.stage==='unknown'||r.stage.endsWith('_wait'))return say('A new request is unavailable. Reconcile the original request first.');if(!r.channelAllowed){r.unsentKind=kind;r.notice='Not sent: this demo channel has no permission. The draft is retained. Ask an operator or restore the authorised channel in demo controls.';render();return;}if(r.manual||r.budget.requests>=r.budget.maxRequests){escalation(r,'Shared command budget exhausted. No new action was sent.');render();return;}if(kind==='booking'&&(!r.consent||r.consent.revision!==r.revision))return say('Current customer consent is required.');if(kind==='collection'&&selected==='SIM'&&(!r.collectionConsent||r.collectionConsent.revision!==r.revision||r.returnAuthority!=='approved'))return say('Current collection consent and return authority are required.');
 const id=selected;if(retry){if(!r.pending||r.pending.kind!==kind||r.stage!=='retry_ready'||r.pending.revision!==r.revision)return say('This exact request cannot be retried after a terms change.');r.pending.attempts++;}else{r.sequence=(r.sequence||0)+1;if(kind==='collection'&&id==='033'&&!r.collectionConsent)r.collectionConsent={object:m.object,date:'2026-03-07',time:'10:00–14:00',address:null,addressSource:'Use existing authorised return record; address value not supplied in snapshot',price:0,currency:'GBP',revision:r.revision,basis:'Customer consent in event-002; address not supplied in snapshot'};const params=structuredClone({consent:r.consent,collectionConsent:r.collectionConsent,requestedDate:r.requestedDate||null,refusalReason:r.refusalReason||null});r.pending={id:`${r.run}-request-${r.sequence}`,kind,previous:r.stage,object:m.object,revision:r.revision,snapshot:r.snapshot,params,body:kind==='booking'?`Book ${slotText(r.consent.slot)}; ${money(r.consent.slot)}.`:kind==='collection'?`Request collection: ${JSON.stringify(r.collectionConsent)}`:kind==='refusal'?`Record item refusal: ${r.refusalReason||'Customer declined the item'}`:(kind==='quote'&&r.requestedDate?`Request current delivery windows for ${m.object} on ${r.requestedDate} and the full surcharge. Do not change the booking before customer consent.`:r.customDraft||m.draft),recipient:kind==='invite'?m.person:['quote','booking'].includes(kind)?'Dispatch / scheduling · Plover Arc Logistics':m.recipient,channel:'Authorised demo channel',expected:kind==='quote'?'Current windows and full prices':kind==='label'?'Matching current RT/TG/DL label':kind==='invite'?'Customer choice and exact consent':'Verified exact task outcome',createdAt:r.clock,attempts:1,status:'sending'};}
 if(!retry&&kind==='quote'&&r.requestedDate)r.rounds++;r.unsentKind=null;r.budget.requests++;const requestId=r.pending.id;r.stage='sending';r.pending.status='sending';r.notice='';r.wait={owner:kind==='invite'?'Customer':m.recipient,next:plusMinutes(r.clock,5),due:plusMinutes(r.clock,30)};log(r,'Request prepared',kind);render();setTimeout(()=>{const q=state.records[id];if(q.stage!=='sending'||q.stop||q.pending?.id!==requestId)return;q.stage={invite:'await_customer',quote:'quote_wait',booking:'booking_wait',label:'label_wait',collection:'collection_wait',investigation:'investigation_wait',refusal:'refusal_saved'}[kind];q.pending.status=kind==='refusal'?'confirmed':'acknowledged';if(kind==='refusal')appendResponse(q,'refusal',true,{refusalRecorded:true});log(q,'Dispatch acknowledged','Local simulation');render();say(kind==='refusal'?'Refusal recorded. Collection remains a separate task.':'Request sent. Task outcome is pending.');},450);}
function appendResponse(r,outcome,accepted,payload={},override={}){const q=r.pending;const x={id:`${q.id}-evidence-${r.responses.length+1}`,requestId:q.id,object:q.object,revision:q.revision,provider:'Verified local simulator',receivedAt:r.clock,outcome,accepted,payload,...override};r.responses.push(x);return x;}
function confirmedStage(kind,stop){return kind==='quote'?(stop?'stopped':'offered'):kind==='invite'?(stop?'stopped':'await_customer'):({booking:'booked',label:'label_ready',collection:'collection_booked',investigation:'investigation_registered',refusal:'refusal_saved'})[kind];}
function responseValid(q,e,revision){return e.requestId===q.id&&e.object===q.object&&e.revision===q.revision&&q.revision===revision;}
function confirmEvent(kindOfReply='result'){const r=rec(),q=r.pending;if(!q||!outstanding(r))return say('No unresolved request to reconcile.');if(['wrong','stale'].includes(kindOfReply)){appendResponse(r,'rejected',false,{claimedResult:'Confirmation'}, {object:kindOfReply==='wrong'?'WRONG-OBJECT':q.object,revision:kindOfReply==='stale'?q.revision-1:q.revision,reason:kindOfReply==='wrong'?'Object does not match request':'Response revision is stale'});r.notice='Response rejected. Current conditions and pending outcome are retained.';log(r,'Evidence rejected',kindOfReply);render();return;}if(kindOfReply==='ack'){appendResponse(r,'acknowledged',true,{message:'Request accepted; task outcome pending'});q.status='acknowledged';log(r,'Acknowledgement only','Task remains pending');render();return;}
 if(!responseValid(q,{requestId:q.id,object:q.object,revision:q.revision},r.revision)){appendResponse(r,'rejected',false,{}, {reason:'Current case revision differs; operator reconciliation required'});escalation(r,'Response no longer matches the current case revision.');render();return;}
 const kind=q.kind;let payload={};if(kind==='quote'){const date=q.params.requestedDate||'10 February 2026';payload={slots:[{id:'q1',date,time:'12:00–14:00',price:8,currency:'GBP'},{id:'q2',date,time:'16:00–18:00',price:10,currency:'GBP'}]};r.slots=structuredClone(payload.slots);r.stage=r.stop?'stopped':'offered';r.revision++;r.selection=null;r.consent=null;}else if(kind==='booking'){if(!q.params.consent)return say('Original consent evidence is missing.');r.consent=structuredClone(q.params.consent);payload={bookingReference:'DEMO-'+q.id,terms:r.consent};r.stage='booked';}else if(kind==='collection'){r.collectionConsent=structuredClone(q.params.collectionConsent);payload={bookingReference:'DEMO-'+q.id,terms:r.collectionConsent};r.stage='collection_booked';}else{r.stage={label:'label_ready',investigation:'investigation_registered',invite:r.stop?'stopped':'await_customer',refusal:'refusal_saved'}[kind];payload=kind==='label'?{returnId:'RT-031',orderId:'TG-031',deliveryId:'DL-031',document:'DEMO-LABEL',version:r.revision}:kind==='refusal'?{refusalRecorded:true}:{registered:true};}
 r.stage=confirmedStage(kind,r.stop);if(kind==='investigation'){r.investigation={reference:'DEMO-INV-'+q.id,next:plusMinutes(r.clock,60),owner:'Carrier investigations team'};payload=structuredClone(r.investigation);}appendResponse(r,'confirmed',true,payload);q.status='confirmed';r.notice='';log(r,'Confirmation received','Local simulator · '+kind);render();say('Verified outcome saved.');}
function demo(){const r=rec(),pending=outstanding(r);modal('Local simulation events',`<p>Case ${selected} · virtual time ${fmtClock(r.clock)}. No external effects.</p><div class="demo-events">${button('Confirmed response received','event-confirm','',!pending)}${button('Acknowledgement only','event-ack','',!pending)}${button('Wrong object response','event-wrong','',!pending)}${button('Stale response revision','event-old','',!pending)}${button('Response lost: outcome unknown','event-unknown','',!r.stage.endsWith('_wait'))}${button('Reconciled: action was not executed','event-none','',r.stage!=='unknown')}${button('No available windows','event-empty','',r.stage!=='quote_wait')}${button('Offer terms changed','event-stale','',!r.slots.length||!['draft','await_customer','offered'].includes(r.stage)||r.stop)}${button('Advance beyond response deadline','event-timeout','',!pending)}${button(r.channelAllowed?'Revoke demo channel permission':'Restore demo channel permission','event-permission')}${button('Label link expired','event-label-expired','',r.stage!=='label_ready')}${selected==='SIM'?button('Return authority is unknown','event-authority'):''}${button('Next stop acknowledgement fails','event-stop-fail')}${mode==='team'?button('Simulate list load failure','event-load-error'):''}</div>`);}
function collectionForm(){const r=rec();if(r.stop||r.returnAuthority!=='approved')return say('Collection is not authorised. Ask the operator for help.');modal('Collection details',`<form id="collection-form"><p class="small muted">Virtual scenario date: ${dateISO(r)}. Choose a date in the next 30 days.</p><div class="field"><label for="pickup-date">Date</label><input type="date" id="pickup-date" required min="${dateISO(r)}" max="${plusMinutes(r.clock,30*1440).slice(0,10)}" value="${plusMinutes(r.clock,1440).slice(0,10)}"></div><div class="field"><label for="pickup-address">Collection address</label><input id="pickup-address" required maxlength="240" placeholder="Enter the address"></div><p>10:00–14:00 UTC · no extra charge · ${meta().object}</p><label class="checkline"><input id="pickup-consent" type="checkbox" required><span>I agree to collection of this return at this address, date, time and price.</span></label><div id="form-error" role="alert"></div><div class="dialog-actions">${button('Back','close')}<button type="submit" class="primary">Request collection</button></div></form>`);}
function operatorForm(){const r=rec();modal('Operator decision',`<form id="operator-form"><input type="hidden" id="decision-revision" value="${r.revision}"><input type="hidden" id="decision-stage" value="${r.stage}"><p>${meta().object} · revision ${r.revision} · ${STATUS[r.stage]?.[0]}</p><p>${esc(meta().summary)}</p><p class="small muted">Saved stage: ${esc(r.help.savedStage)}. ${r.budget.requests}/${r.budget.maxRequests} commands used. Decisions do not replace customer consent or grant carrier authority.</p><div class="field"><label for="decision">Next step</label><select id="decision"><option value="clarify">Request more information</option><option value="continue">Continue the authorised task</option><option value="stop">Stop new actions</option></select></div><div class="field"><label for="decision-note">Reason and explanation for the customer</label><textarea id="decision-note" required maxlength="600"></textarea></div><label class="checkline"><input type="checkbox" id="decision-reviewed" required><span>I reviewed the current facts and version.</span></label>${r.rounds>=r.dateAllowance?'<label class="checkline"><input type="checkbox" id="decision-extra"><span>Allow one additional date search within the unchanged shared command budget.</span></label>':''}<div id="form-error" role="alert"></div><details><summary>Demo validation controls</summary>${button('Change case version while reviewing','decision-stale')}</details><div class="dialog-actions">${button('Cancel','close')}<button class="primary" type="submit">Save decision</button></div></form>`);}
function helpRequest(){const r=rec();if(r.help&&r.help.status!=='resolved')return say('Your current help request is still open.');r.help={status:'requested',note:'',requestedAt:r.clock,due:plusMinutes(r.clock,60),savedStage:r.stage,revision:r.revision};const id=selected,run=r.run;log(r,'Help requested','Awaiting queue acceptance');render();setTimeout(()=>{const q=state.records[id];if(q.run!==run||q.help?.status!=='requested')return;q.help.status='queued';log(q,'Queue accepted the request');render();},450);}
function stopRequest(){const r=rec();r.stop=true;r.stopState='requested';if(outstanding(r))r.stage='unknown';else if(!terminal(r))r.stage='stopped';const id=selected,run=r.run;log(r,'Stop requested','New actions blocked immediately; registration pending');render();setTimeout(()=>{const q=state.records[id];if(q.run!==run||q.stopState!=='requested')return;q.stopState=q.failStopAck?'failed':'acknowledged';q.failStopAck=false;log(q,q.stopState==='failed'?'Stop acknowledgement failed':'Stop acknowledged','New commands remain blocked');render();},450);}
function rows(){if(state.loadError)return `<div class="empty"><h3>Cases could not be loaded</h3><p>The local demo source is temporarily unavailable. Your saved work is retained.</p>${button('Retry loading','reload-cases')}</div>`;const ids=Object.keys(META).filter(id=>{const r=state.records[id],m=META[id];const match=`${id} ${m.person} ${m.title} ${m.object}`.toLowerCase().includes(query.toLowerCase());return match&&(filter==='all'||filter==='done'&&terminal(r)||filter==='mine'&&r.help&&r.help.status!=='resolved'||filter==='waiting'&&outstanding(r)||filter==='attention'&&(!outstanding(r)&&!terminal(r)&&!r.stop||r.help&&r.help.status!=='resolved'));});return ids.length?ids.map(id=>{const r=state.records[id],m=META[id];return `<button class="case-item ${id===selected?'active':''}" data-case="${id}" aria-current="${id===selected}"><div class="row"><strong>${id==='SIM'?'Refusal demo':'Delivery '+id}</strong><span>${m.object}</span></div><h3>${m.title}</h3>${badge(r)}<span class="small">${m.person}</span><span class="small">Owner: ${r.help&&r.help.status!=='resolved'?'Team operator':'Delivery coordinator'}</span><span class="small">Next: ${nextStep(r)}</span></button>`;}).join(''):`<div class="empty"><h3>No matching cases</h3>${button('Clear filters','clear-filter')}</div>`;}
function queueView(){let ids=Object.keys(META).filter(id=>state.records[id].help);ids=ids.filter(id=>queueFilter==='all'||queueFilter==='open'&&state.records[id].help.status!=='resolved'||queueFilter==='resolved'&&state.records[id].help.status==='resolved');return `<div class="page-heading"><div><div class="eyebrow">Human review</div><h1>Operator queue</h1><p>Exceptions retain their original stage, evidence and shared budget.</p></div><label>Queue filter<select id="queue-filter"><option value="open" ${queueFilter==='open'?'selected':''}>Open requests</option><option value="all" ${queueFilter==='all'?'selected':''}>All requests</option><option value="resolved" ${queueFilter==='resolved'?'selected':''}>Resolved</option></select></label></div><div class="queue">${ids.length?ids.map(id=>{const r=state.records[id],h=r.help;return `<section class="card queue-card"><div><h2>${META[id].object} · ${META[id].title}</h2><p>${esc(h.status.replaceAll('_',' '))} · saved stage: ${esc(h.savedStage)}</p><p>Requested ${fmtClock(h.requestedAt)} · due ${fmtClock(h.due)} · owner: Team operator</p><p>${esc(h.note||'Customer or team requested help')}</p>${h.answer?`<div class="notice">Customer answer: ${esc(h.answer)}</div>`:''}</div><div class="actions"><button data-case="${id}" data-open="true">Open case</button><button class="primary" data-operator="${id}" ${['requested','awaiting_customer','resolved'].includes(h.status)?'disabled':''}>${h.status==='queued'?'Take ownership':'Record decision'}</button></div></section>`;}).join(''):`<section class="card empty"><h2>Queue is clear</h2><p>Routine dispatch requests stay in case details.</p>${button('Go to cases','go-cases')}</section>`}</div>`;}
function extras(r){return `${r.stop?`<div class="notice" role="status"><strong>${r.stopState==='requested'?'Stop requested · acknowledgement pending':r.stopState==='failed'?'Stop acknowledgement failed · commands remain blocked':'New actions stopped'}</strong><p>Earlier confirmed outcomes remain valid. This does not cancel delivery or return.</p>${r.stopState!=='acknowledged'?button('Verify stop registration','check'):''}</div>`:''}${r.notice?`<div class="notice pending" role="status">${esc(r.notice)}</div>`:''}${r.help?.status==='awaiting_customer'?`<section class="task-section"><h2>More information needed</h2><p>${esc(r.help.note)}</p>${button('Answer the operator','answer','primary')}</section>`:''}${r.help?.status==='resolved'&&r.help.decision==='continue'?`<div class="notice success"><strong>Decision accepted for revision ${r.help.revision}</strong><p>${esc(r.help.note)}</p><p>${nextStep(r)}</p></div>`:''}${waitCard(r)}`;}
function overview(){return extras(rec())+baseOverview();}
function clientContent(){const r=rec();if(r.resultClosed)return `<h2>Result saved</h2><p>You can return to your confirmed outcome at any time in this demo.</p>${button('View saved result','reopen-result','primary')}`;let content=baseClientContent();if(r.stop&&r.stage==='refusal_saved')content='<h2>Refusal recorded</h2><p>The confirmed refusal is retained. New collection actions are stopped.</p>';if(r.stage==='refusal_saved'&&r.returnAuthority!=='approved'&&!r.stop)content=`<h2>Refusal recorded</h2><p>Return authority is ${esc(r.returnAuthority)}. No collection can be requested.</p><div class="notice pending">Owner: Team operator. Your refusal remains recorded.</div>${button('Ask an operator','help','primary',r.help&&r.help.status!=='resolved')}`;if(terminal(r))content+=`<div class="actions">${button('Close result','close-result','quiet')}</div>`;return extras(r)+content;}
function resultText(r){if(r.stage==='investigation_registered')return `Investigation ${esc(r.investigation?.reference)} registered. Next update: ${fmtClock(r.investigation?.next||plusMinutes(r.clock,60))}. Owner: carrier investigations team. The delivery dispute remains open; loss is not established.`;if(r.stage==='collection_booked'){const c=r.collectionConsent;return `Collection booked: ${esc(c?.date||'7 March 2026')}, ${esc(c?.time||'10:00–14:00')} UTC. Address: ${esc(c?.address||'Not supplied in snapshot; request refers to the existing RT-033 return record')}. ${money(c||{price:0})}. Reference: DEMO-${esc(r.pending?.id)}. Physical receipt is not yet confirmed.`;}return baseResultText(r);}
function prepView(){const p=state.prep,c=p.config;return `<div class="page-heading"><div><div class="eyebrow">Offline engineering workspace</div><h1>Prepare simulation</h1><p>Configure, check and explicitly enable one version-bound local run.</p></div><span id="prep-phase" class="badge">${esc(p.phase)}</span></div><div class="prep-grid"><section class="card"><h2>Run configuration</h2><form id="prep-form"><div class="field"><label for="prep-case">Input snapshot</label><select id="prep-case">${Object.keys(META).map(id=>`<option value="${id}" ${id===c.caseId?'selected':''}>${id} · ${META[id].title}</option>`).join('')}</select></div><div class="field"><label for="prep-clock">Scenario clock (UTC)</label><input id="prep-clock" type="datetime-local" required value="${c.clock.slice(0,16)}"></div><div class="facts"><div class="field"><label for="prep-workflow">Workflow version</label><input id="prep-workflow" value="${esc(c.workflow)}" required></div><div class="field"><label for="prep-simulator">Simulator version</label><input id="prep-simulator" value="${esc(c.simulator)}" required></div><div class="field"><label for="prep-requests">Shared command limit</label><input id="prep-requests" type="number" min="1" max="10" value="${c.maxRequests}" required></div><div class="field"><label for="prep-checks">Shared check limit</label><input id="prep-checks" type="number" min="1" max="5" value="${c.maxChecks}" required></div></div><div class="field"><label for="prep-channel">Demo channel permission</label><select id="prep-channel"><option value="allowed" ${c.channel==='allowed'?'selected':''}>Allowed</option><option value="blocked" ${c.channel==='blocked'?'selected':''}>Blocked</option></select></div><div class="field"><label for="prep-rehearsal">Local transition rehearsal</label><select id="prep-rehearsal"><option value="normal" ${c.rehearsal!=='fault'?'selected':''}>Verified outcome and wrong-evidence rejection</option><option value="fault" ${c.rehearsal==='fault'?'selected':''}>Inject incorrect outcome (failure demonstration)</option></select></div><button type="submit" class="primary">Run configuration checks</button></form></section><section class="card" id="prep-evidence"><h2>Checks and enablement</h2>${p.rehearsal?`<h3>Local rehearsal trace</h3><p class="small muted">Shared outcome transition and evidence guard, using a test fixture. This does not execute a real delivery or certify all cases.</p>${p.rehearsal.map(x=>`<div class="notice ${x.passed?'success':'unknown'}"><strong>${esc(x.scenario)}</strong><p>Expected: ${esc(x.expected)} · Actual: ${esc(x.actual)} · ${x.passed?'passed':'failed'}</p></div>`).join('')}`:''}${p.phase==='failed'?`<div class="notice unknown" role="alert"><strong>Checks failed</strong><ul>${p.errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div><p>Correct the configuration and rerun checks. Nothing was enabled.</p>`:''}${['ready','launching','running'].includes(p.phase)?`<div class="notice success">Configuration revision ${p.revision} passed checks.</div><p>Workflow ${esc(c.workflow)} · ${esc(c.simulator)} · snapshot ${esc(c.caseId)}</p><p class="small muted">Input hash: ${esc(window.SOURCE_DATA?.[c.caseId]?.input_hash||'synthetic-refusal-v1')}</p>`:'<p>Validate the input, supported versions, permissions, clock and finite limits before enablement.</p>'}${p.phase==='running'?`<h3>Run registered</h3><p class="small">${esc(p.runId)}</p><p>Only snapshot ${p.launched.caseId} is included in this run. Historical evaluation outcomes are excluded.</p><button data-case="${p.launched.caseId}" data-open="true">Open enabled case</button>`:`${button(p.phase==='launching'?'Registering run…':'Enable checked local run','enable-run','primary',p.phase!=='ready')}`}<p class="small muted">Enablement applies only to this local simulator. It grants no real carrier access.</p><hr><h3>Current case events</h3><p>Case ${selected} · ${fmtClock(rec().clock)}</p>${button('Set an event for '+selected,'demo')}${button('Restart demo','reset','quiet')}</section></div>`;}
function prepRead(){return {caseId:$('#prep-case').value,clock:$('#prep-clock').value+':00Z',workflow:$('#prep-workflow').value.trim(),simulator:$('#prep-simulator').value.trim(),maxRequests:Number($('#prep-requests').value),maxChecks:Number($('#prep-checks').value),channel:$('#prep-channel').value,rehearsal:$('#prep-rehearsal').value};}
function prepCheck(){const p=state.prep;p.config=prepRead();p.revision++;const c=p.config;p.errors=[];if(!META[c.caseId])p.errors.push('Input snapshot is unavailable.');if(c.workflow!=='v6')p.errors.push('This prototype supports workflow v6 only.');if(c.simulator!=='local-v4')p.errors.push('This prototype supports simulator local-v4 only.');if(!Number.isFinite(Date.parse(c.clock))||dateISO({clock:c.clock})!==scenarioClock(c.caseId).slice(0,10))p.errors.push('Scenario clock must be on the selected snapshot date.');if(c.channel!=='allowed')p.errors.push('No permitted demo channel.');if(c.maxRequests<1||c.maxRequests>10||c.maxChecks<1||c.maxChecks>5)p.errors.push('Limits are outside the permitted finite range.');const kind=META[c.caseId].kind,expected=({booking:'booked',quote:'offered',label:'label_ready',collection:'collection_booked',investigation:'investigation_registered',refusal:'refusal_saved'})[kind];const actual=c.rehearsal==='fault'?'unknown':confirmedStage(kind,false);const probe={id:'CHECK',object:META[c.caseId].object,revision:1};p.rehearsal=[{scenario:'Verified '+kind+' outcome',expected,actual,passed:actual===expected},{scenario:'Wrong-object evidence',expected:'rejected',actual:responseValid(probe,{requestId:'CHECK',object:'WRONG',revision:1},1)?'accepted':'rejected',passed:!responseValid(probe,{requestId:'CHECK',object:'WRONG',revision:1},1)}];if(p.rehearsal.some(x=>!x.passed))p.errors.push('Local transition rehearsal differs from the expected workflow outcome. Inspect the trace and correct the setting.');p.phase=p.errors.length?'failed':'ready';p.checked=JSON.stringify(c);render('#main h1');}
function prepInvalidate(){state.prep.phase='draft';save();$('#prep-phase').textContent='draft';$('#prep-evidence').innerHTML='<h2>Configuration changed</h2><p>Previous check evidence does not apply to these edits. Run checks again before enablement.</p><p>Any previously registered run keeps its frozen configuration.</p>'+button('Enable checked local run','enable-run','primary',true);}
function enableRun(){const p=state.prep;if(p.phase!=='ready'||JSON.stringify(p.config)!==p.checked)return say('The current configuration must pass checks first.');p.phase='launching';const rev=p.revision;render();setTimeout(()=>{if(state.prep.revision!==rev||state.prep.phase!=='launching')return;const c=state.prep.config,r=fresh().records[c.caseId];r.clock=c.clock;r.budget.maxRequests=c.maxRequests;r.budget.maxChecks=c.maxChecks;r.configVersion=c.simulator;state.records[c.caseId]=r;state.prep.phase='running';state.prep.launched=structuredClone(c);state.prep.runId=r.run;selected=c.caseId;render('#main h1');},450);}
function action(a){const r=rec();if(a==='send')return submit(r.unsentKind||(meta().kind==='booking'?'invite':meta().kind));if(a==='check')return checkOutcome();if(a==='help')return helpRequest();if(a==='collection-form')return collectionForm();if(a==='confirm-stop'){close();return stopRequest();}if(a==='back-choice'){clientStep='choose';r.consent=null;render('input[name=slot]');return;}if(a==='reload-cases'){state.loadError=false;render('#case-search');return;}if(a==='close-result'){r.resultClosed=true;render('#main h1');return;}if(a==='reopen-result'){r.resultClosed=false;render('#main h1');return;}if(a==='enable-run')return enableRun();if(a==='decision-stale'){r.revision++;save();$('#form-error').textContent='Demo: the case changed. Saving this decision will be rejected.';return;}if(a==='answer'){modal('Answer the operator',`<form id="answer-form"><p>${esc(r.help?.note)}</p><div class="field"><label for="operator-answer">Your answer</label><textarea id="operator-answer" required maxlength="600"></textarea></div><div class="dialog-actions">${button('Cancel','close')}<button type="submit" class="primary">Send answer to operator</button></div></form>`);return;}
 if(a==='dates'&&(r.rounds>=r.dateAllowance||r.manual)){if(!r.help||r.help.status==='resolved')helpRequest();r.notice='Date-search limit reached. The operator owns the next decision; you can answer any clarification here.';render();return;}if(a==='refusal-dialog'){modal('Record refusal of this item?',`<p>Confirm refusal for SIM-REFUSAL. Collection and refund are separate.</p><div class="field"><label for="refusal-reason">Reason (optional)</label><textarea id="refusal-reason" maxlength="400"></textarea></div><div class="dialog-actions">${button('Back','close')}${button('Confirm refusal','confirm-refusal','primary')}</div>`);return;}if(a==='confirm-refusal'){r.refusalReason=$('#refusal-reason')?.value.trim()||'Customer declined the item';close();return submit('refusal');}
 if(a==='label'&&r.labelExpired){modal('Label cannot be opened',`<div class="notice unknown" role="alert">The document link has expired. The verified return remains unchanged.</div><p>Retry document access without creating another return or label request.</p>${button('Refresh document access','label-refresh','primary')}`);return;}if(a==='label-refresh'){r.labelExpired=false;close();say('Document access restored in the local simulator.');return baseAction('label');}
 if(a.startsWith('event-')){close();if(a==='event-confirm')return confirmEvent();if(a==='event-ack')return confirmEvent('ack');if(a==='event-wrong')return confirmEvent('wrong');if(a==='event-old')return confirmEvent('stale');if(a==='event-permission'){r.channelAllowed=!r.channelAllowed;r.notice=r.channelAllowed?'Authorised demo channel restored.':'Demo channel permission revoked; no new commands can be sent.';}else if(a==='event-timeout'){r.clock=plusMinutes(r.wait.due,1);escalation(r,'Response deadline reached. The operator owns the unresolved outcome.');}else if(a==='event-label-expired')r.labelExpired=true;else if(a==='event-authority'){r.returnAuthority='unknown';r.collectionConsent=null;r.revision++;escalation(r,'Return authority is unknown. Verify it before arranging collection.');}else if(a==='event-load-error')state.loadError=true;else if(a==='event-stop-fail'){r.failStopAck=true;r.notice='Demo: the next stop acknowledgement will fail; commands will remain blocked.';}else if(a==='event-unknown'){r.stage='unknown';r.pending.status='unknown';log(r,'Outcome unknown','Response lost; do not resend');}else if(a==='event-none'){appendResponse(r,'not_executed',true,{executed:false});r.pending.status='not_executed';r.stage=r.stop?'stopped':'retry_ready';log(r,'Non-execution verified','Only the original intent can be retried');}else if(a==='event-empty'){appendResponse(r,'no_options',true,{slots:[]});r.pending.status='confirmed';r.stage=r.stop?'stopped':'no_options';r.slots=[];r.selection=null;r.consent=null;log(r,'No windows available','Verified simulator response');}else if(a==='event-stale'){r.revision++;r.selection=null;r.consent=null;clientStep='choose';r.stage='offered';r.slots=r.slots.map((s,i)=>({...s,time:i?'14:00–16:00':'17:00–19:00',price:s.price+2}));r.notice='Offer updated: the windows and full surcharges changed. Review and consent again.';log(r,'Terms changed','Old consent is invalid');}render();return;}
 return baseAction(a);
}
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.action)return action(b.dataset.action);if(b.dataset.section){section=b.dataset.section;render(`[data-section="${section}"]`);return;}if(b.dataset.case){selected=b.dataset.case;if(b.dataset.open)section='cases';tab='overview';clientStep='choose';history.replaceState(null,'','?case='+selected);render('.detail-head h1');return;}if(b.dataset.tab){tab=b.dataset.tab;render(`[data-tab="${tab}"]`);return;}if(b.dataset.operator){selected=b.dataset.operator;const r=rec();if(r.help.status==='queued'){r.help.status='accepted';log(r,'Operator took ownership');render(`[data-operator="${selected}"]`);}else operatorForm();}});
app.addEventListener('input',e=>{if(e.target.id==='case-search'){query=e.target.value;$('#case-rows').innerHTML=rows();}if(e.target.closest('#prep-form'))prepInvalidate();});
app.addEventListener('change',e=>{if(e.target.id==='case-filter'){filter=e.target.value;$('#case-rows').innerHTML=rows();}if(e.target.id==='queue-filter'){queueFilter=e.target.value;render('#queue-filter');}if(e.target.id==='client-case'){selected=e.target.value;history.replaceState(null,'','?case='+selected);clientStep='choose';render('#client-case');}if(e.target.name==='slot'){rec().selection=e.target.value;rec().consent=null;save();const b=app.querySelector('[data-action=review]');if(b)b.disabled=false;}if(e.target.id==='prep-case'){$('#prep-clock').value=scenarioClock(e.target.value).slice(0,16);prepInvalidate();}});
app.addEventListener('submit',e=>{if(e.target.id==='prep-form'){e.preventDefault();prepCheck();}});
dialog.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)action(b.dataset.action);});
dialog.addEventListener('submit',e=>{e.preventDefault();const r=rec(),id=e.target.id;if(!e.target.reportValidity())return;if(id==='edit-form'){r.customDraft=$('#draft-text').value.trim();if(!r.customDraft)return;close();log(r,'Draft updated','Not sent');render('[data-action=edit]');}
 if(id==='dates-form'){const date=$('#date-input').value;r.requestedDate=new Date(date+'T12:00:00Z').toLocaleDateString('en-GB',{year:'numeric',month:'long',day:'numeric',timeZone:'UTC'});r.slots=[];r.selection=null;r.consent=null;clientStep='choose';close();submit('quote');}
 if(id==='collection-form'){const date=$('#pickup-date').value,address=$('#pickup-address').value.trim();if(!address||date<dateISO(r)||date>plusMinutes(r.clock,30*1440).slice(0,10)){$('#form-error').textContent='Choose an allowed date and enter a collection address.';return;}r.collectionConsent={object:meta().object,date,time:'10:00–14:00',address,price:0,currency:'GBP',revision:r.revision,agreedAt:r.clock,basis:'Explicit customer checkbox after reviewing all terms'};close();submit('collection');}
 if(id==='answer-form'){const answer=$('#operator-answer').value.trim();if(!answer)return;r.help.answer=answer;r.help.status='queued';r.help.revision=r.revision;log(r,'Customer clarification received','Operator review required; budget unchanged');close();render('#main h1');say('Answer saved in the operator queue. No booking was made.');}
 if(id==='operator-form'){const d=$('#decision').value,n=$('#decision-note').value.trim(),rev=Number($('#decision-revision').value),stage=$('#decision-stage').value;if(!n)return;let error='';if(rev!==r.revision||stage!==r.stage)error='Decision rejected: the case changed. Close this form and review the current facts.';if(d==='continue'&&(r.stop||r.stage==='unknown'))error='Cannot resume new commands while stopped or while the original outcome is unknown. Reconcile or request clarification.';if(d==='continue'&&r.budget.requests>=r.budget.maxRequests)error='Shared command budget is exhausted. Keep the pending obligation with the operator or stop new actions.';if(d==='continue'&&r.rounds>=r.dateAllowance&&!$('#decision-extra')?.checked)error='Continuation needs an explicit one-search allowance within the unchanged command budget.';if(error){$('#form-error').className='notice unknown';$('#form-error').textContent=error;r.decisions.push({accepted:false,decision:d,reason:error,revision:rev,time:r.clock});log(r,'Operator decision rejected',error);save();return;}const entry={accepted:true,decision:d,note:n,revision:rev,stage,time:r.clock};r.decisions.push(entry);Object.assign(r.help,{note:n,decision:d,revision:rev,status:d==='clarify'?'awaiting_customer':'resolved'});if(d==='continue'){r.manual=false;if($('#decision-extra')?.checked)r.dateAllowance++;r.notice='Operator decision accepted. Resume the saved task; customer consent is still required.';}log(r,'Operator decision accepted',d);close();if(d==='stop')stopRequest();else render('#main h1');say('Decision saved. No business command was executed.');}
});
window.addEventListener('storage',e=>{if(e.key===CFG.storageKey&&e.newValue){try{const s=JSON.parse(e.newValue);if(s.version===CFG.version){state=s;render();}}catch{}}});
let queueFilter='open';
render();
